css:
.sl-hero-glass {
  background-color: #0f172a;
  color: #f8fafc;
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 85vh;
  padding-block: clamp(4rem, 8vw, 6.5rem);
}
.sl-hero-glass .sl-glass-bg {
  filter: blur(8px);
  transform: scale(1.08);
}
.sl-hero-glass .sl-glass-scrim {
  background: rgba(15, 23, 42, 0.68);
}
.sl-hero-glass .sl-glass-panel {
  background: rgba(15, 23, 42, 0.62);
  border: 1px solid rgba(248, 250, 252, 0.25);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  color: #f8fafc;
}
.sl-hero-glass .sl-glass-gem {
  color: #f8fafc;
}
.sl-hero-glass .sl-glass-title {
  letter-spacing: 0.02em;
  color: #ffffff;
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-glass .sl-glass-copy {
  color: #e2e8f0;
}
.sl-hero-glass .sl-glass-divider {
  border-top: 1px solid rgba(248, 250, 252, 0.25);
}
.sl-hero-glass .sl-glass-input {
  background-color: rgba(15, 23, 42, 0.72);
  border: 1px solid rgba(248, 250, 252, 0.4);
  color: #ffffff;
}
.sl-hero-glass .sl-glass-input::placeholder {
  color: #cbd5e1;
}
.sl-hero-glass .sl-glass-input:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 2px;
  border-color: #ffffff;
  background-color: rgba(15, 23, 42, 0.85);
}
.sl-hero-glass .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-glass .sl-btn-primary:hover,
.sl-hero-glass .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-glass .sl-apply-status {
  color: #bbf7d0;
  font-weight: 600;
}

js:
(function() {
  'use strict';
  function initGlassHeroes() {
    var roots = document.querySelectorAll('.sl-hero-glass');
    if (!roots.length) return;
    roots.forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var form = root.querySelector('.sl-apply-form');
      var input = root.querySelector('.sl-glass-input');
      var status = root.querySelector('.sl-apply-status');
      if (!form || !input || !status) return;
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        var email = (input.value || '').trim();
        if (!email) return;
        status.textContent = 'Application received for ' + email + '. We will send cohort details shortly.';
        status.classList.remove('d-none');
        form.reset();
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initGlassHeroes);
  } else {
    initGlassHeroes();
  }
})();
